const C_CORE_UTIL_SOURCE_TEMPLATE = `/**
 * @file {{baseName}}.c
 * @brief Implementation of the QPM C core utility bundle.
 */
#include "{{headerFile}}"

#include <ctype.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

/**
 * @brief Implements the QpmUtil_CopyString operation.
 * @param dst See the matching header for semantic details.
 * @param dstSize See the matching header for semantic details.
 * @param src See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
int QpmUtil_CopyString(char *dst, size_t dstSize, const char *src)
{
    if (dst == NULL || dstSize == 0)
    {
        return -1;
    }
    if (src == NULL)
    {
        src = "";
    }
    strncpy(dst, src, dstSize - 1);
    dst[dstSize - 1] = '\\0';
    return 0;
}

/**
 * @brief Implements the QpmUtil_Trim operation.
 * @param text See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
char *QpmUtil_Trim(char *text)
{
    char *end;

    if (text == NULL)
    {
        return NULL;
    }

    while (*text != '\\0' && isspace((unsigned char)*text))
    {
        ++text;
    }

    end = text + strlen(text);
    while (end > text && isspace((unsigned char)*(end - 1)))
    {
        --end;
    }
    *end = '\\0';

    return text;
}

/**
 * @brief Implements the QpmUtil_GetTimestamp operation.
 * @param buffer See the matching header for semantic details.
 * @param bufferSize See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
int QpmUtil_GetTimestamp(char *buffer, size_t bufferSize)
{
    time_t now;
    struct tm localTime;

    if (buffer == NULL || bufferSize == 0)
    {
        return -1;
    }

    now = time(NULL);
#if defined(_WIN32)
    if (localtime_s(&localTime, &now) != 0)
    {
        buffer[0] = '\\0';
        return -1;
    }
#else
    {
        struct tm *localTimePtr = localtime(&now);
        if (localTimePtr == NULL)
        {
            buffer[0] = '\\0';
            return -1;
        }
        localTime = *localTimePtr;
    }
#endif

    if (strftime(buffer, bufferSize, "%Y-%m-%d %H:%M:%S", &localTime) == 0)
    {
        buffer[0] = '\\0';
        return -1;
    }

    return 0;
}

/**
 * @brief Implements the QpmUtil_ReadIniValue operation.
 * @param iniPath See the matching header for semantic details.
 * @param key See the matching header for semantic details.
 * @param value See the matching header for semantic details.
 * @param valueSize See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
int QpmUtil_ReadIniValue(const char *iniPath, const char *key, char *value, size_t valueSize)
{
    FILE *file;
    char line[512];
    size_t keyLength;

    if (iniPath == NULL || key == NULL || value == NULL || valueSize == 0)
    {
        return -1;
    }

    value[0] = '\\0';
    keyLength = strlen(key);
    file = fopen(iniPath, "r");
    if (file == NULL)
    {
        return -1;
    }

    while (fgets(line, sizeof(line), file) != NULL)
    {
        char *cursor = QpmUtil_Trim(line);
        char *separator;

        if (cursor == NULL || cursor[0] == '\\0' || cursor[0] == '#' || cursor[0] == ';' || cursor[0] == '[')
        {
            continue;
        }
        if (strncmp(cursor, key, keyLength) != 0)
        {
            continue;
        }

        separator = cursor + keyLength;
        separator = QpmUtil_Trim(separator);
        if (separator == NULL || separator[0] != '=')
        {
            continue;
        }

        ++separator;
        separator = QpmUtil_Trim(separator);
        QpmUtil_CopyString(value, valueSize, separator);
        fclose(file);
        return 0;
    }

    fclose(file);
    return 1;
}
`;

