function buildLuaExecSourceTemplate(): string {
  let text = C_PYTHON_EXEC_SOURCE_TEMPLATE
    .replace(/QpmPython/g, 'QpmLua')
    .replace(/QPM_PYTHON/g, 'QPM_LUA')
    .replace(/QpmPy_/g, 'QpmLua_')
    .replace(/pythonExe/g, 'luaExe')
    .replace(/Python/g, 'Lua')
    .replace(/python/g, 'lua');

  text = text.replace('    int unbuffered;\n', '');
  text = text.replace('    QpmLua_CopyString(config->luaExe, sizeof(config->luaExe), "lua3");', '    QpmLua_CopyString(config->luaExe, sizeof(config->luaExe), "lua");');
  text = text.replace('    config->unbuffered = 1;\n', '');
  text = text.replace(
`        if (QpmLua_AppendCommandPart(&commandLine, &commandSize, &commandCapacity, config->luaExe) != 0 ||
            (config->unbuffered && QpmLua_AppendCommandPart(&commandLine, &commandSize, &commandCapacity, "-u") != 0) ||
            QpmLua_AppendCommandPart(&commandLine, &commandSize, &commandCapacity, config->scriptPath) != 0)`,
`        if (QpmLua_AppendCommandPart(&commandLine, &commandSize, &commandCapacity, config->luaExe) != 0 ||
            QpmLua_AppendCommandPart(&commandLine, &commandSize, &commandCapacity, config->scriptPath) != 0)`);
  text = text.replace(
`            argv[index++] = (char *)config->luaExe;
            if (config->unbuffered)
            {
                argv[index++] = (char *)"-u";
            }
            argv[index++] = (char *)config->scriptPath;`,
`            argv[index++] = (char *)config->luaExe;
            argv[index++] = (char *)config->scriptPath;`);
  text = text.replace(/argCount \+ 4/g, 'argCount + 3');
  return text;
}

const C_LUA_EXEC_SOURCE_TEMPLATE = buildLuaExecSourceTemplate();

