const ERROR_HEADER_TEMPLATE = `/**
 * @file {{headerFile}}
 * @brief QPM C configurable error-management API.
 *
 * @details
 * This generated bundle header documents the module directly in the file
 * copied into the user project. It summarizes the public API scope, common
 * applications and the minimum code needed to verify integration.
 *
 * @par Main features
 * - loads error logging options from an INI file;
 * - stores the last error code and message;
 * - writes bounded log files when enabled;
 * - can mirror errors to stderr;
 * - provides macros for goto-based cleanup flows.
 *
 * @par Typical applications
 * - C programs generated by QPM starters;
 * - test executables that need a simple error label pattern;
 * - small tools where a full logging framework is unnecessary.
 *
 * @par Usage notes
 * - Initialize the module once at program start.
 * - Use the generated ERROR_LABEL pattern to centralize cleanup code.
 * - Configure enabled, mirrorToStderr, maxLogLines and logPath in the generated INI file.
 *
 * @par Example of use
 * @code{.c}
 * #include "{{headerFile}}"
 * 
 * QpmError_InitDefaults();
 * QpmError_LoadConfig("qpm_error.ini");
 * QpmError_Report(12, "Device not ready", __FILE__, __LINE__, QPM_ERROR_FUNCTION);
 * error:
 * QpmError_Log("cleanup after error code %d", g_qpmErrorCode);
 * @endcode
 */
#ifndef {{guard}}
#define {{guard}}

#ifdef __cplusplus
extern "C" {
#endif

#include <stddef.h>

#ifndef QPM_ERROR_MESSAGE_SIZE
#define QPM_ERROR_MESSAGE_SIZE 512
#endif

#ifndef QPM_ERROR_PATH_SIZE
#define QPM_ERROR_PATH_SIZE 1024
#endif

#define ERROR_LABEL error

typedef struct QpmErrorConfig
{
    int enabled;
    int mirrorToStderr;
    int maxLogLines;
    char logPath[QPM_ERROR_PATH_SIZE];
} QpmErrorConfig;

extern int g_qpmErrorCode;
extern QpmErrorConfig g_qpmErrorConfig;

void QpmError_InitDefaults(void);
int QpmError_LoadConfig(const char *iniPath);
void QpmError_SetEnabled(int enabled);
void QpmError_SetLogFile(const char *filePath);
void QpmError_Log(const char *format, ...);
void QpmError_Report(int code, const char *message, const char *file,
                     int line, const char *functionName);

#if defined(_MSC_VER)
#  define QPM_ERROR_FUNCTION __FUNCTION__
#else
#  define QPM_ERROR_FUNCTION __func__
#endif

#define QPM_ERR_INFZ(code, message) \\
    do { \\
        int qpmErrorCodeLocal = (code); \\
        if (qpmErrorCodeLocal < 0) { \\
            g_qpmErrorCode = qpmErrorCodeLocal; \\
            QpmError_Report(qpmErrorCodeLocal, (message), __FILE__, __LINE__, QPM_ERROR_FUNCTION); \\
            goto ERROR_LABEL; \\
        } \\
    } while (0)

#define QPM_ERR_INFEQZ(code, message) \\
    do { \\
        int qpmErrorCodeLocal = (code); \\
        if (qpmErrorCodeLocal <= 0) { \\
            g_qpmErrorCode = qpmErrorCodeLocal; \\
            QpmError_Report(qpmErrorCodeLocal, (message), __FILE__, __LINE__, QPM_ERROR_FUNCTION); \\
            goto ERROR_LABEL; \\
        } \\
    } while (0)

#define QPM_ERR_CHCK_INFZ(expression) \\
    QPM_ERR_INFZ((expression), #expression)

#define QPM_ERR_CHCK_INFEQZ(expression) \\
    QPM_ERR_INFEQZ((expression), #expression)

#define QPM_ERR_PTR(pointer) \\
    do { \\
        if ((pointer) == NULL) { \\
            g_qpmErrorCode = -999; \\
            QpmError_Report(g_qpmErrorCode, "NULL pointer: " #pointer, __FILE__, __LINE__, QPM_ERROR_FUNCTION); \\
            goto ERROR_LABEL; \\
        } \\
    } while (0)

#ifdef __cplusplus
}
#endif

#endif /* {{guard}} */
`;

const ERROR_SOURCE_TEMPLATE = String.raw`/**
 * @file {{baseName}}.c
 * @brief Implementation of the QPM C error management bundle.
 */
#include "{{headerFile}}"

#include <ctype.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#if defined(_WIN32)
#  define QPM_STRICMP _stricmp
#else
#  include <strings.h>
#  define QPM_STRICMP strcasecmp
#endif

int g_qpmErrorCode = 0;
QpmErrorConfig g_qpmErrorConfig;

static void QpmError_CopyString(char *dst, size_t dstSize, const char *src)
{
    if (dst == NULL || dstSize == 0)
        return;
    if (src == NULL)
        src = "";
    strncpy(dst, src, dstSize - 1);
    dst[dstSize - 1] = '\0';
}

static char *QpmError_Trim(char *text)
{
    char *end;
    while (*text != '\0' && isspace((unsigned char)*text))
        ++text;
    end = text + strlen(text);
    while (end > text && isspace((unsigned char)*(end - 1)))
        --end;
    *end = '\0';
    return text;
}

static int QpmError_ParseBool(const char *text, int defaultValue)
{
    if (text == NULL)
        return defaultValue;
    if (QPM_STRICMP(text, "true") == 0 || QPM_STRICMP(text, "yes") == 0 || strcmp(text, "1") == 0 || QPM_STRICMP(text, "on") == 0)
        return 1;
    if (QPM_STRICMP(text, "false") == 0 || QPM_STRICMP(text, "no") == 0 || strcmp(text, "0") == 0 || QPM_STRICMP(text, "off") == 0)
        return 0;
    return defaultValue;
}

static int QpmError_FormatTimestamp(char *buffer, size_t bufferSize)
{
    time_t now;
    struct tm localTime;

    if (buffer == NULL || bufferSize == 0)
        return -1;

    now = time(NULL);
#if defined(_WIN32)
    if (localtime_s(&localTime, &now) != 0)
    {
        buffer[0] = '\0';
        return -1;
    }
#else
    {
        struct tm *localTimePtr = localtime(&now);
        if (localTimePtr == NULL)
        {
            buffer[0] = '\0';
            return -1;
        }
        localTime = *localTimePtr;
    }
#endif

    if (strftime(buffer, bufferSize, "%d/%m/%Y - %H:%M:%S", &localTime) == 0)
    {
        buffer[0] = '\0';
        return -1;
    }
    return 0;
}

static void QpmError_MakeSeparator(char *buffer, size_t bufferSize, char ch, size_t count)
{
    size_t i;
    if (buffer == NULL || bufferSize == 0)
        return;
    if (count >= bufferSize)
        count = bufferSize - 1;
    for (i = 0; i < count; ++i)
        buffer[i] = ch;
    buffer[count] = '\0';
}

static void QpmError_TrimLogIfNeeded(void)
{
    FILE *file;
    char line[512];
    int lineCount = 0;

    if (!g_qpmErrorConfig.enabled || g_qpmErrorConfig.maxLogLines <= 0 || g_qpmErrorConfig.logPath[0] == '\0')
        return;

    file = fopen(g_qpmErrorConfig.logPath, "r");
    if (file == NULL)
        return;

    while (fgets(line, sizeof(line), file) != NULL)
        ++lineCount;
    fclose(file);

    if (lineCount > g_qpmErrorConfig.maxLogLines)
    {
        file = fopen(g_qpmErrorConfig.logPath, "w");
        if (file != NULL)
            fclose(file);
    }
}

void QpmError_InitDefaults(void)
{
    g_qpmErrorCode = 0;
    g_qpmErrorConfig.enabled = 1;
    g_qpmErrorConfig.mirrorToStderr = 1;
    g_qpmErrorConfig.maxLogLines = 5000;
    QpmError_CopyString(g_qpmErrorConfig.logPath, sizeof(g_qpmErrorConfig.logPath), "logs/error.log");
}

int QpmError_LoadConfig(const char *iniPath)
{
    FILE *file;
    char line[1024];

    QpmError_InitDefaults();
    if (iniPath == NULL || iniPath[0] == '\0')
        return 0;

    file = fopen(iniPath, "r");
    if (file == NULL)
        return -1;

    while (fgets(line, sizeof(line), file) != NULL)
    {
        char *trimmed = QpmError_Trim(line);
        char *equals;
        char *key;
        char *value;
        if (trimmed[0] == '\0' || trimmed[0] == '#' || trimmed[0] == ';' || trimmed[0] == '[')
            continue;
        equals = strchr(trimmed, '=');
        if (equals == NULL)
            continue;
        *equals = '\0';
        key = QpmError_Trim(trimmed);
        value = QpmError_Trim(equals + 1);

        if (QPM_STRICMP(key, "enabled") == 0)
            g_qpmErrorConfig.enabled = QpmError_ParseBool(value, g_qpmErrorConfig.enabled);
        else if (QPM_STRICMP(key, "mirror_to_stderr") == 0 || QPM_STRICMP(key, "mirrorToStderr") == 0)
            g_qpmErrorConfig.mirrorToStderr = QpmError_ParseBool(value, g_qpmErrorConfig.mirrorToStderr);
        else if (QPM_STRICMP(key, "max_log_lines") == 0 || QPM_STRICMP(key, "maxLogLines") == 0)
            g_qpmErrorConfig.maxLogLines = atoi(value);
        else if (QPM_STRICMP(key, "log_path") == 0 || QPM_STRICMP(key, "logPath") == 0)
            QpmError_CopyString(g_qpmErrorConfig.logPath, sizeof(g_qpmErrorConfig.logPath), value);
    }

    fclose(file);
    return 0;
}

void QpmError_SetEnabled(int enabled)
{
    g_qpmErrorConfig.enabled = enabled ? 1 : 0;
}

void QpmError_SetLogFile(const char *filePath)
{
    QpmError_CopyString(g_qpmErrorConfig.logPath, sizeof(g_qpmErrorConfig.logPath), filePath);
}

void QpmError_Log(const char *format, ...)
{
    char message[2048];
    FILE *file;
    va_list args;

    va_start(args, format);
    vsnprintf(message, sizeof(message), format, args);
    va_end(args);
    message[sizeof(message) - 1] = '\0';

    if (g_qpmErrorConfig.enabled && g_qpmErrorConfig.logPath[0] != '\0')
    {
        QpmError_TrimLogIfNeeded();
        file = fopen(g_qpmErrorConfig.logPath, "a");
        if (file != NULL)
        {
            fputs(message, file);
            fflush(file);
            fclose(file);
        }
    }

    if (g_qpmErrorConfig.mirrorToStderr)
        fputs(message, stderr);
}

void QpmError_Report(int code, const char *message, const char *file,
                     int line, const char *functionName)
{
    char timestamp[64];
    char sideSep[32];
    char fullSep[128];
    char header[160];

    if (QpmError_FormatTimestamp(timestamp, sizeof(timestamp)) != 0)
        QpmError_CopyString(timestamp, sizeof(timestamp), "unknown time");

    QpmError_MakeSeparator(sideSep, sizeof(sideSep), '=', 26);
    snprintf(header, sizeof(header), "%s%s%s", sideSep, timestamp, sideSep);
    QpmError_MakeSeparator(fullSep, sizeof(fullSep), '=', strlen(header));

    QpmError_Log("%s\n"
                 "Code: %d\n"
                 "Message: %s\n"
                 "Error at:\n"
                 "\tFile: %s\n"
                 "\tLine: %d\n"
                 "\tFunction: %s\n"
                 "%s\n",
                 header,
                 code,
                 message != NULL ? message : "(none)",
                 file != NULL ? file : "(unknown)",
                 line,
                 functionName != NULL ? functionName : "(unknown)",
                 fullSep);
}
`;

