  private async generateQtTest(projectDirectory: string): Promise<NewFileGenerationResult | undefined> {
    const className = await vscode.window.showInputBox({
      title: 'Create a Qt Test class',
      prompt: 'Test class name',
      value: 'ExampleTest',
      validateInput: validateCppClassName
    });
    if (!className) return undefined;

    const stem = `tst_${qtFileStem(className).replace(/^tst_/, '')}`;
    const target = await this.askTargetPath(projectDirectory, '.cpp', path.join('tests', stem), 'Qt Test source file');
    if (!target) return undefined;
    const mocName = `${path.basename(target, path.extname(target))}.moc`;
    const content = `#include <QtTest/QTest>

class ${className} final : public QObject
{
    Q_OBJECT

private slots:
    void initTestCase()
    {
    }

    void example()
    {
        QCOMPARE(1 + 1, 2);
    }

    void cleanupTestCase()
    {
    }
};

QTEST_APPLESS_MAIN(${className})
#include "${mocName}"
`;
    return this.writeFiles([{ absolutePath: target, contents: toCrlf(content) }], target);
  }

